    fun destroy() {
        coroutineScope.cancel()
    }

    fun flushData() {
        val populatedEntries = seriesCache.populatedEntries()
        if (populatedEntries.isEmpty()) return
        val existingChart = chartView.chart ?: return
        val populatedData = chartUpdater.sync(populatedEntries, existingChart, graphViewport.rangeProvider)
        val snapshot = populatedData.toCoordinates()
        coroutineScope.launch {
            modelProducer.runTransaction {
                lineModel {
                    snapshot.forEach { (x, y) ->
                        series(x = x, y = y)
                    }
                }
            }
        }
    }

    fun newSeries(wiFiDetail: WiFiDetail): Boolean = !seriesExists(wiFiDetail)

    fun calculateGraphType(): Int =
        runCatching {
            with(MessageDigest.getInstance("MD5")) {
                update(
                    MainContext.INSTANCE.mainActivity.packageName
                        .toByteArray(),
                )
                val digest: ByteArray = digest()
                digest.contentHashCode()
            }
        }.getOrDefault(TYPE1)

    fun show() {
        chartView.visibility = View.VISIBLE
    }

    fun gone() {
        chartView.visibility = View.GONE
    }

    fun size(value: Int): Int = if (value == TYPE1 || value == TYPE2 || value == TYPE3) SIZE_MAX else SIZE_MIN

    private fun updateConnectionColor(
        seriesData: SeriesData,
        connected: Boolean,
    ) {
        if (seriesData.connected == connected) return
        seriesData.graphColor =
            if (connected) {
                graphColors.addColor(seriesData.graphColor.primary)
                graphColors.connectedColor
            } else {
                graphColors.graphColor()
            }
        seriesData.connected = connected
    }

    private fun seriesExists(wiFiDetail: WiFiDetail): Boolean = seriesCache.contains(wiFiDetail)

    private fun seriesTitle(wiFiDetail: WiFiDetail): String =
        "${wiFiDetail.wiFiIdentifier.ssid} ${wiFiDetail.wiFiSignal.channelDisplay()}"
}

@OpenClass
internal class Cache {
    private val scanResults: ArrayDeque<List<ScanResult>> = ArrayDeque(MAXIMUM)
    private var count: Int = COUNT_MIN
    var wifiInfo: WifiInfo? = null

    fun scanResults(): List<CacheResult> =
        combineCache()
            .groupingBy { CacheKey(it.BSSID, it.ssid()) }
            .aggregate { _, accumulator: CacheResult?, element, first ->
                CacheResult(element, calculate(first, element, accumulator))
            }.values
            .toList()

    fun add(scanResults: List<ScanResult>) {
        count = if (count >= MAXIMUM * FACTOR) COUNT_MIN else count + 1
        val size = size()
        while (this.scanResults.size >= size) {
            this.scanResults.removeLastOrNull()
        }
        this.scanResults.addFirst(scanResults)
    }

    fun first(): List<ScanResult> = scanResults.first()

    fun last(): List<ScanResult> = scanResults.last()

    fun size(): Int =
        if (sizeAvailable) {
            val settings = MainContext.INSTANCE.settings
            if (settings.cacheOff()) {
                MINIMUM
            } else {
                with(settings.scanSpeed()) {
                    when {
                        this < 2 -> MAXIMUM
                        this < 5 -> MAXIMUM - 1
                        this < 10 -> MAXIMUM - 2
                        else -> MINIMUM
                    }
                }
            }
        } else {
            MINIMUM
        }

    private fun calculate(
        first: Boolean,
        element: ScanResult,
        accumulator: CacheResult?,
    ): Int {
        val average: Int = if (first) element.level else (accumulator!!.average + element.level) / DENOMINATOR
        return (if (sizeAvailable) average else average - SIZE * (count + count % FACTOR) / DENOMINATOR)
            .coerceIn(LEVEL_MINIMUM, LEVEL_MAXIMUM)
    }

    private fun combineCache(): List<ScanResult> = scanResults.flatten().sortedWith(comparator())

    private fun comparator(): Comparator<ScanResult> =
        compareBy<ScanResult> {
            it.BSSID
        }.thenBy { it.ssid() }.thenBy { it.level }

    private val sizeAvailable: Boolean get() = MainContext.INSTANCE.configuration.sizeAvailable

    companion object {
        private const val MINIMUM: Int = 1
        private const val MAXIMUM: Int = 4
        private const val SIZE: Int = MINIMUM + MAXIMUM
        private const val LEVEL_MINIMUM: Int = -100
        private const val LEVEL_MAXIMUM: Int = 0
        private const val FACTOR: Int = 3
        private const val DENOMINATOR: Int = 2
        private const val COUNT_MIN: Int = 2
    }
}
